mapper.insert:

    SELECT
        'CPRQ'||
        LPAD(NVL(TO_NUMBER(SUBSTR(MAX(COMPANY_REVIEW_QUESTION_NO), LENGTH('CPRQ' ) + 1)), 0) + 1, 6, '0')
    FROM COMPANY_REVIEW_QUESTION

INSERT INTO COMPANY_REVIEW_QUESTION (
	COMPANY_REVIEW_QUESTION_NO
		, COMPANY_REVIEW_NO
		, REVIEW_SUBJECT_CODE
		, COMPANY_REVIEW_SCORE
	) VALUES (
	#{companyReviewQuestionNo}
		, #{companyReviewNo}
		, #{reviewSubjectCode}
		, #{companyReviewScore}
	)

mapper.update:
UPDATE COMPANY_REVIEW_QUESTION
	SET 
	COMPANY_REVIEW_NO = #{companyReviewNo}
		, REVIEW_SUBJECT_CODE = #{reviewSubjectCode}
		, COMPANY_REVIEW_SCORE = #{companyReviewScore}
WHERE COMPANY_REVIEW_QUESTION_NO = #{companyReviewQuestionNo}
